a := [1,2,3]
fn(cb(x)) { a.push(9)
 return x }
r := a.map(cb)
print(r.stringify())
print(a.stringify())

a := [1,2,3]
fn(cb(x)) { a.pop()
 return x }
r := a.map(cb)
print(r.stringify())
print(a.stringify())

fn(bad(x)) { return x / 0 }
a := [1,2]
r := a.map(bad)

a := [1,2,3]
fn(replacement()) { print(a.stringify())
 return [9] }
r := a.splice(1,1,replacement())
print(r.stringify())
print(a.stringify())

a := [1,2,3]
try { a.splice(1,1,9) } catch(e) { print("caught") }
print(a.stringify())

a := [1,2,3]
fn(replacement()) { throw error("stop") }
try { a.splice(1,1,replacement()) } catch(e) { print("caught") }
print(a.stringify())

a := [1]
fn(v()) { print("value")
 return 9 }
r := a.insert(-1,v())

fn(f()) { a := [1,2]
 cb := () => { a.pop()
 return a.length() }
print(cb())
print(a.stringify()) }
f()

trace := ""
a := [3,1,2]
fn(ka(x)) { trace = trace + "a" + x.to_string()
 return x }
fn(kb(x)) { trace = trace + "b" + x.to_string()
 return 0 }
r := a.sort_by(ka,"asc",kb,"desc")
print(trace)
print(r.stringify())

a := [3,1,2]
fn(cb(x)) { a.pop()
 return x }
r := a.sort_by(cb)
print(r.stringify())
print(a.stringify())
